qualified_questions.sparql_query:
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT (COUNT(DISTINCT ?player) AS ?numberOfPlayers)
WHERE {
  ?specificPlayer VideoGameOntology:isFriendWithPlayer ?player .
  ?player VideoGameOntology:ownsAchievement ?achievement .
  ?game VideoGameOntology:hasAchievement ?achievement .
  FILTER NOT EXISTS {
    ?game VideoGameOntology:hasAchievement ?otherAchievement .
    FILTER(?otherAchievement != ?achievement)
    FILTER NOT EXISTS {
      ?player VideoGameOntology:ownsAchievement ?otherAchievement
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT (COUNT(DISTINCT ?achievementType) AS ?count)
WHERE {
  {
    ?achievementType rdfs:subClassOf* VideoGameOntology:Achievement
  }
  UNION
  {
    ?achievementType rdf:type owl:Class .
    ?achievementType rdfs:subClassOf VideoGameOntology:Achievement
  }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?session) AS ?sessionCount)
WHERE {
    ?player VideoGameOntology:username ?username .
    ?session rdf:type VideoGameOntology:Session ;
             VideoGameOntology:startTime ?startTime ;
             VideoGameOntology:endTime ?endTime .
    FILTER(?startTime >= "2023-01-01T00:00:00"^^xsd:dateTime && ?endTime <= "2023-01-31T23:59:59"^^xsd:dateTime)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX ex: <http://example.org/>

SELECT (COUNT(?achievement) AS ?numberOfAchievements)
WHERE {
  ?player ex:unlockedAchievement ?achievement ;
          ex:playsGame ?game .
  ?achievement ex:inGame ?game .
}
